from pathlib import Path
from datetime import datetime,timezone
import json,re,hashlib,xml.etree.ElementTree as E,sys
W=Path(__file__).resolve().parent;D=W/'sources/review-p134a-p151'
IDS='p134a p134b p135 p136 p137 p138 p139 p140 p141 p142 p143 p144 p145 p145a p146 p147 p148 p149 p150 p151'.split()
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
hashtext=lambda s:hashlib.sha256(s.encode()).hexdigest()
def save(p,o):p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
notes={
'p134a':'Alle drei Absätze, vier Datenquellen, drei Empfängergruppen und beide Buchstaben der Kooperationsgruppe gelesen. Ergänzt: Pflichtübermittlung inländischer Stellen versus mögliche Spontanhinweise; Art.84-Vorbehalt; Löschung ab Ende des Erhebungsjahrs mit konkret richtigem Beispiel; abschließende Weiterverarbeitungserlaubnis nur für Empfänger Nr.2/3. Keine unbeschränkte Behördenakte oder private Akteneinsicht abgeleitet.',
'p134b':'Beide Absätze vollständig geprüft. Aufgabenerfüllung/Information/Untersuchung/Beteiligung in Abs.1 von Übermittlungsbefugnis in Abs.2 getrennt; Kontrollzweck im Empfängerstaat, Erforderlichkeit, Zweck- und Löschungsmitteilung entfaltet. Keine automatische Geltung deutschen Löschungsrechts für jede ausländische Akte behauptet. Beispiel konkretisiert zulässige Herkunftsnachweise und unzulässige pauschale Personalaktensendung.',
'p135':'Alle drei Absätze mit vier Berechtigtengruppen und sämtlichen Verweisen geprüft. Wichtig präzisiert: tätigkeitsbereichsbezogene Unterlassungsberechtigung ist weiter als besondere Erzeugernamenverfolgung der im Register bezeichneten Vereinigung. Verschuldensunabhängige Unterlassung, eigener Nutzerschaden bei Vorsatz/Fahrlässigkeit und Zustimmung getrennt. §§14a Abs.2/18/19/19a/19c und §128 Abs.2/3 mit §19b/14Abs.7/19d gelesen; keine schrankenlose Übernahme aller Markenansprüche.',
'p136':'Gesamten Kurztext, §20 und parallelen §129 gelesen; erhalten. Keine selbständige feste Frist oder gleichgesetzte Kenntnis sämtlicher Anspruchsteller. Beispiel Kontrollbericht und Abgrenzung zur Zweimonatsbeschwerde in §133 richtig. Vollständige BGB-Fristberechnung wird ausdrücklich nicht vorgetäuscht; Restanspruch nur entsprechend dem Verweis angesprochen.',
'p137':'Beide Sätze und §8Abs.2Nr.9/§132a gelesen. Internationaler Schutzstatus in der Union, Produktgruppe und subsidiärer Schutzumfang nach Art.40/41 getrennt. Ergänzt, dass die Spanne §§134–136 auch die Buchstabenparagraphen 134a/134b umfasst. Keine automatische Schutzwirkung jeder ausländischen Registrierung; konkretes fiktives Vertriebsbeispiel erhalten.',
'p138':'Beide Absätze vollständig geprüft und erhalten. Verfahrensmodalitäten §§130–132a samt internationalen Registrierungen/Gebühren, Bundesministerium ohne Bundesratszustimmung, vollständige/teilweise Subdelegation durch Verordnung richtig. Aus der Ermächtigung keine bereits existierende Dateiform oder Änderung materieller EU-Schutzvoraussetzungen erfunden. Tatsächliche Ausführungsregel ist für konkrete Antragspraxis zusätzlich nachzulesen.',
'p139':'Alle Absätze, zwei Schutzgruppen, vier Regelungsgegenstände, zwei Länderkompetenzen und Delegations-/Kontaktpflichten gelesen. Präzisiert: Erfordernis beziehungsweise unionsrechtliche Erlaubnis für Ergänzung, Kontrolle beim Verbringen/Ein-/Ausfuhr versus vor/nach Markt, Zulassung versus bloßer Kontaktmeldung. Rückverweis und nur teilweise Erfassung im §145Abs.2Nr.2 klargestellt. Fiktive Prüfstelle und praktische Checkliste sachbezogen.',
'p140':'Vier Absätze gegen XML geprüft, bestehende Kommentierung erhalten. Streitwertunabhängige LG-Zuständigkeit, Konzentration/Länderübertragung, Eilerleichterung nur für Unterlassung und keine Befreiung vom materiellen Anspruchsnachweis. Kosten des Patentanwalts VII vollständig erneut gelesen und frisch abgeglichen; Rn.9–12/19–21/28 stützen begrenzte Erstattung und offene konkrete Erforderlichkeit. Keine automatische Vollerstattung und keine Gleichsetzung mit Anwaltsmandatsvergütung.',
'p141':'Gesamten Text und amtlichen §14UWG-Einzeltext gelesen. Zu enge Formulierung eines einzigen ausschließlichen Wettbewerbsortes korrigiert: §14UWG enthält mehrere Anknüpfungen und Beschränkungen; §141 löst für kennzeichenbezogene UWG-Ansprüche die besondere Bindung, schafft aber keinen beliebigen Gerichtsstand. Sachliche/örtliche/internationale Zuständigkeit und Schlüssigkeit bleiben getrennt; bestehendes Beispiel passt.',
'p142':'Alle drei Absätze einschließlich drei Zahlungsrichtungen in Abs.2 gelesen. Präzisiert: eigener Gerichtskosten-/Anwaltsteilwert, begrenzte Erstattung an Gegner bei eigener Kostenlast und Beitreibung eigener Anwaltgebühren gegen belasteten Gegner nach dessen Wert. Keine beiderseitige Streitwertreduktion. Antrag/Glaubhaftmachung erheblicher Gefährdung, Frist vor Hauptsacheverhandlung, spätere Erhöhung als Ausnahme und Gegnergehör vollständig; Beispiel erhalten.',
'p143':'Alle Absätze einschließlich Wegfall 1a/7, fünf Nummern und Buchstaben a/b gelesen. Strafvarianten von zivilen Verboten und Kennzeichnungsmitteln unterschieden; besondere Bekanntheits-/Ermöglichungsabsicht, allgemeiner Vorsatz laut frisch gelesenem §15StGB, Grund-/Qualifikationsrahmen, Versuch, Antragsausnahme, Einziehung/Adhäsionsvernichtung und Bekanntmachung entfaltet. Geschäftlicher Verkehr ist nicht schon Gewerbsmäßigkeit; fiktive Etikettenhandlung konkret subsumiert.',
'p144':'Zwei Absätze und drei Alternativen samt fester Verordnungsfassung vollständig gelesen. Nr.3 mit unähnlichen Waren/Leistungen und Absicht nicht zivilrechtlich erweitert; Strafrahmen und genaue Abs.2-Verweisung erfasst. BGH 3StR225/20 Tenor/Rn.1–13 vollständig gelesen und frisch amtlich verifiziert: historische Identitätskonstellation, keine automatische Strafbarkeitslücke, Einfuhr ohne Eigenhand. Grenzen und Umnummerierung aus Art.5Nr.31 geprüft; kein 2026-Urteil suggeriert.',
'p145':'Alle sechs Absätze, vier Abs.1-Gruppen, beide Abs.2-Nummern und drei Abs.3-Alternativen gelesen. Vorsatzregel §10OWiG frisch amtlich geprüft und nur Abs.2/4 ausdrücklich fahrlässig; Rückverweiserfordernis und konkrete Kontrollhandlungen, Selbstbelastungsverweigerung, feste EU-Fassung, Eigenerklärung, drei differenzierte Höchstbeträge und begrenzte BfJ-Zuweisung präzisiert. §160Abs.1 gelesen, ohne historische Fassung zu ersetzen. Kein Bußgeld für jede Verordnungshandlung behauptet.',
'p145a':'Vollständigen Satz und §145Abs.1/3 gelesen; erhalten. Kennzeichnungsbeseitigung vor Vernichtung bei Unmöglichkeit, keine automatische Anwendung auf bloße Abs.2/4-Kontroll-/Erklärungspflichten. Fiktiv entfernbare Aufkleber versus integrierte Kennzeichnung; zivilrechtliche Vernichtung und zollrechtliche Einziehung sachgerecht unterschieden.',
'p146':'Beide Absätze und EU-Vorrang vollständig gelesen. Antrag/Sicherheitsleistung/offensichtliche Verletzung, tatsächlich stattfindende Binnenkontrollen, Mitteilung beider Seiten und konkreter Informationsumfang, Geheimnisgrenze der Besichtigung und Art.10-Eingriff richtig. Hinzugefügt: nur Ein-/Ausfuhr im Wortlaut, keine zusätzliche Durchfuhr wie in §151. Keine pauschale Aussage zum gesamten EU-Zollanwendungsbereich.',
'p147':'Alle vier Absätze geprüft. Korrigiert: noch nicht zugegangene beantragte Entscheidung genügt für maximale Zweiwochenverlängerung, nicht nur noch nicht beschiedener Antrag. Erste Widerspruchsfrist und zweite Frist ab Zustellung der Widerspruchsmitteilung an Antragsteller sauber getrennt. Unverzügliche Erklärung/Rücknahme, vollziehbare gerichtliche Verwahrungs-/Verfügungsanordnung und Haftungsrisiko erfasst; kein unbegrenzter Arrest bis Hauptsacheende.',
'p148':'Alle drei Absätze gelesen; unverändert erhalten. Generalzolldirektion, einjährige oder kürzer beantragte Geltung und Wiederholung, Kosten §178AO, Antragstellergehör und sofortige Beschwerde AG–OLG zutreffend. Sicherheit von Kosten, allgemeine Antragslaufzeit von konkreten §147-Fristen getrennt. Keine Gebührenbeträge oder ungeprüften Rechtsmittelfristen ergänzt.',
'p149':'Gesamten Tatbestand gegen XML gelesen; erhalten. Ursprüngliche Unberechtigung plus warenbezogene Aufrechterhaltung oder nicht unverzügliche Erklärung, kausaler Schaden des Verfügungsberechtigten und kein zusätzlich genannter Verschuldensnachweis richtig. Erschöpfungsbeispiel mit §24 abgeglichen, ohne jeden Erstbeschlagnahmefehler automatisch der Norm gleichzustellen. Kein vermeintlicher neuer Zollhaftungsfall aus Suchsnippet zitiert.',
'p150':'Vollständige Kollisions-/Ergänzungsregel gelesen; erhalten. Nur §148Abs.1/2 und §149 übernommen, soweit keine entgegenstehende Unionsbestimmung; §147 und §148Abs.3 nicht pauschal importiert. Fiktives Drittlandsverfahren und Warnung vor Übertragung nationaler Zweiwochenfolge richtig. Keine ungeprüfte eigene EU-Frist oder pauschale EU-Zuständigkeitszuweisung hinzugefügt.',
'p151':'Alle vier Absätze und neue internationale Schutzgrundlage gelesen; erhalten. EU-Vorrang, offensichtliche Verletzung, Ein-/Aus-/Durchfuhr, tatsächliche Binnenkontrollen, behördliche Beseitigungsmaßnahmen vor Einziehung bei Nichtbefolgung/Untunlichkeit, AG–OLG-Rechtsmittel korrekt. Kein Antrags-/Sicherheitsmodell des §146 importiert und Einziehung nicht mit Vernichtung gleichgesetzt. Abschlusscheckliste angemessen und spezifisch.'}
assert list(notes)==IDS
before=json.loads((D/'before-commentary.json').read_text());prior=json.loads((D/'prior-review-result.json').read_text())
current={m[1]:m[2].strip() for p in (W/'commentary').glob('*.md') for m in re.finditer(r'^=== (\S+)\s*\n(.*?)(?=^=== |\Z)',p.read_text(),re.M|re.S)}
assert len(current)==191 and set(before)==set(current)
changed=[i for i in IDS if before[i]!=current[i]];assert len(changed)==12
assert all(before[i]==current[i] for i in before if i not in IDS)
units={u['id']:u for u in map(json.loads,(W/'units.jsonl').read_text().splitlines())}
root=E.parse(D/'markeng.xml').getroot();compact=lambda s:re.sub(r'\s+','',s)
findings=[]
for i in IDS:
 u=units[i];n=next(n for n in root.findall('norm') if n.findtext('metadaten/enbez')==u['label'])
 assert compact(u['text'])==compact(''.join(n.find('textdaten/text/Content').itertext()))
 findings.append(dict(id=i,label=u['label'],disposition='corrected' if i in changed else 'retained',finding=notes[i],paragraphs_and_lists_read=True,meaning_examples_crossrefs_authorities_repetition_checked=True,statutory_wording_agreement=True,official_doknr=n.attrib['doknr'],statutory_sha256=hashtext(u['text']),commentary_before_sha256=hashtext(before[i]),commentary_after_sha256=hashtext(current[i])))
casechecks=[]
for slug,docket,ids in [('patentanwaltskosten','I ZB 59/19',['p140']),('gemeinschaftsmarke','3 StR 225/20',['p144'])]:
 r=E.parse(D/(slug+'.xml')).getroot();s=compact((D/(slug+'-local.md')).read_text());ps=[compact(''.join(p.itertext())) for t in ['tenor','tatbestand','entscheidungsgruende','gruende'] for p in r.findall(t+'//p')];ps=[p for p in ps if p]
 assert ps and all(p in s for p in ps)
 casechecks.append(dict(slug=slug,court='BGH',date=r.findtext('entsch-datum'),docket=docket,xml_sha256=sha(D/(slug+'.xml')),local_sha256=sha(D/(slug+'-local.md')),official_nonempty_paragraphs_compared=len(ps),read_full_text=True,supported_reviewed_ids=ids,card='cases/bgh-'+('patentanwaltskosten' if slug=='patentanwaltskosten' else 'gemeinschaftsmarke-strafbarkeit')+'.md'))
save(D/'case-comparison.json',casechecks)
cumulative=list(dict.fromkeys(prior['cumulative_reviewed_ids']+IDS));assert len(cumulative)==180
coverage=json.loads((W/'completeness-independent.json').read_text());q=json.loads((W/'quality-report.json').read_text());assert coverage['ok']
validated='--validated' in sys.argv;technical=json.loads((W/'validation.json').read_text()) if validated else None
if validated:assert technical['ok'] and technical['verbatim_ratio']==1.0 and not q['broken_local_links'] and not q['repeated_long_sentences'] and not q['placeholder_matches']
now=datetime.now(timezone.utc).isoformat()
limits=['Exactly the assigned 20 units reviewed; 11 whole-book units remain outside this task. No whole-book completion or external professional approval.','Case law selective: BGH I ZB 59/19 reread and BGH 3 StR 225/20 added after full-text review; 15 other cards retained without substantive rereview. No exhaustive later-case audit.','No independent full-text revalidation of every EU regulation, international agreement, historical version or implementing ordinance. National current statute, all operative references and both 2026 amendment/commencement acts checked.','UWG §14, StGB §15 and OWiG §10 freshly read as targeted official provisions; not a complete amendment-history audit of those laws.','Firecrawl extraction unavailable for lack of credits; validated direct official HTTP bodies used. Later-amendment search selective, not exhaustive BGBl pipeline audit.']
result=dict(complete=validated,task='bounded_independent_second_pass',units_reviewed=20,reviewed_ids=IDS,decisive_date='2026-10-19',reviewed_at=now,unresolved_blockers=[],findings=findings,limitations=limits,changed_ids=changed,retained_ids=[i for i in IDS if i not in changed],whole_book_complete=False,work_baseline_commit=(D/'baseline-commit.txt').read_text().strip(),baseline_evidence='sources/review-p134a-p151/before-commentary.json',baseline_evidence_sha256=sha(D/'before-commentary.json'),unchanged_unassigned_units=171,unassigned_commentary_unchanged=True,prior_review_result='sources/review-p134a-p151/prior-review-result.json',cumulative_reviewed_ids=cumulative,cumulative_reviewed_units=180,remaining_second_pass_units=11,case_checks=casechecks,source_preflight='preflight-result.json',source_verification='sources/verification.json',technical_validation=technical,technical_validation_pending=not validated,completeness=dict(expected=191,parsed=191,missing=coverage['missing'],extra=coverage['unexpected'],xml_character_mismatch=coverage['xml_character_mismatch']),quality=dict(broken_links=q['broken_local_links'],repeated_long_sentences=q['repeated_long_sentences'],placeholder_matches=q['placeholder_matches']))
save(W/'review-result.json',result)
status=json.loads((W/'status.json').read_text());status.update(stage='bounded_second_pass_complete' if validated else 'bounded_second_pass_validation_pending',task_scope='Exactly p134a–p151 including p134b and p145a; no whole-book completion.',reviewed_ids=IDS,units_reviewed=20,review_result='review-result.json',review_completed_at=now if validated else None,whole_book_review_complete=False,independent_second_pass='Current 20 reviewed; 180 cumulatively reviewed, 11 pending',updated_at=now,remaining_limitations=limits,unresolved_blockers=[],cumulative_reviewed_ids=cumulative,cumulative_reviewed_units=180,remaining_second_pass_units=11,commentary_characters=sum(map(len,current.values())))
status['source_checks']['latest_verification']=now
for c in casechecks:
 if c['docket'] not in {x['docket'] for x in status['case_law_sources']}:status['case_law_sources'].append({k:c[k] for k in ['court','date','docket','card','read_full_text']})
status['case_law_provenance']='One new and one existing BGH decision fully read and freshly verified in this batch; 15 other cards retained without renewed substantive review.'
status['quality_checks'].update(output_local_links=q['checked_output_links'],broken_links=q['broken_local_links'],repeated_paragraphs=q['exact_repeated_paragraphs'],repeated_long_sentences=q['repeated_long_sentences'],other_commentary_blocks='All 171 unassigned blocks unchanged against baseline '+result['work_baseline_commit'],unchanged_commentary_units=179,retained_reviewed_units=8,corrected_reviewed_units=12)
if validated:status['validation_result']=technical
save(W/'status.json',status)
verification=json.loads((W/'sources/verification.json').read_text());fetches=json.loads((D/'fetches.json').read_text())
for f in fetches:
 assert sha(W/f['path'])==f['sha256'] and f['http_status']==200
 if f['path'] not in {x['path'] for x in verification['fetches']}:verification['fetches'].append(f)
verification['last_verified_at']=now;verification['bounded_review_p134a_p151'].update(case_comparison='sources/review-p134a-p151/case-comparison.json',case_full_text_read=True,external_references=['UWG §14','StGB §15','OWiG §10'])
save(W/'sources/verification.json',verification)
pf=json.loads((W/'preflight-result.json').read_text());pf['bounded_review_p134a_p151_recheck'].update(assigned_version_analysis='sources/review-p134a-p151/assigned-version-review.json',supplementary_source_limitations=limits[2:])
if validated:pf['bounded_review_p134a_p151_recheck']['technical_validation']=technical
save(W/'preflight-result.json',pf)
print(json.dumps(dict(complete=validated,units_reviewed=20,corrected=12,retained=8,cumulative_reviewed=180,remaining=11,unassigned_unchanged=171,case_paragraphs=sum(c['official_nonempty_paragraphs_compared'] for c in casechecks))))
